import * as prettier from "prettier";

export async function formatExactRouteSource(releaseCode, output) {
  const withoutMissingMap = releaseCode.replace(/\n?\/\/# sourceMappingURL=.*?\.map\s*$/, "\n");
  const formatted = await prettier.format(withoutMissingMap, {
    parser: "babel",
    printWidth: 120,
  });
  const normalized = formatted.replace(
    "This application was built with linking (tree shaking) disabled. \nPublished applications will be significantly smaller if you install wasm-tools workload. \n",
    'This application was built with linking (tree shaking) disabled.${" "}\nPublished applications will be significantly smaller if you install wasm-tools workload.${" "}\n',
  );
  const rewritten = normalized.replace(
    /(["'`])\.\/([^"'`]+\.js)\1/g,
    (_match, quote, file) => `${quote}@exact-chunk/${file}${quote}`,
  );
  return `// Generated by scripts/promote-exact-renderer-route-sources.mjs.\n// Release-faithful semantic owner for ${output}; only import specifiers differ.\n${rewritten}`;
}
